async function toggleStatus(id, completed) {
  try {
    const res = await fetch(`/api/todos/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ completed })
    });
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      showItemError(id, data.error || 'Update failed');
      return;
    }
  } catch (e) {
    showItemError(id, 'Could not reach the server');
    return;
  }
  fetchTodos();
}

function showItemError(id, message) {
  const li = document.querySelector(`li[data-id="${id}"]`);
  if (!li) return;
  let alert = li.querySelector('[role="alert"]');
  if (!alert) {
    alert = document.createElement('span');
    alert.setAttribute('role', 'alert');
    alert.style.cssText = 'color:red;font-size:0.85rem;margin-left:8px;';
    li.appendChild(alert);
  }
  alert.textContent = message;
}

